def solve(n, k, x):
    # Calculate the number of sets of integers that sum to n and are disjoint from {1, 2, ..., k} \ {x}
    def count_sets(target, exclude):
        # Calculate the number of ways to choose k integers from 1 to n-1, excluding the excluded integers
        choices = math.comb(n - 1, k - len(exclude))
        # For each possible set of integers, check if their sum equals the target and they are disjoint from the excluded set
        return sum(1 for s in combinations(range(1, n), k) if sum(s) == target and not any(e in s for e in exclude))

    # Calculate the number of sets of integers that sum to n-1 and are disjoint from {1, 2, ..., k} \ {x}
    sets_of_n_1 = count_sets(n-1, {x})
    # Calculate the number of sets of integers that sum to n-2 and are disjoint from {1, 2, ..., k} \ {x}
    sets_of_n_2 = count_sets(n-2, {x})
    # If there is a way to get n-1 using k-1 integers, and a way to get 1 using 1 integer, then there is a way to get n using k integers
    if sets_of_n_1 and sets_of_n_2:
        return "YES\n" + str(sets_of_n_1 + 1) + "\n" + "\n".join(map(str, range(1, k+1)))

    # If there is no way to get n using k integers, return NO
    return "NO\n"

