    health = list(map(int, input().split()))
    visited = set()

    def dfs(current_health, current_index):
        if current_index == n:
            return 1

        min_spells = float('inf')
        for i in range(current_index, n):
            if health[i] > 0 and (i not in visited):
                for j in range(i+1, n):
                    if health[j] > 0 and (j not in visited):
                        visited.update({i, j})
                        new_health = list(health)
                        new_health[i] -= 1
                        new_health[j] -= 1
                        spells = dfs(tuple(new_health), current_index + 1)
                        if spells != float('inf'):
                            min_spells = min(min_spells, spells + 2)
                        new_health[i] += 1
                        new_health[j] += 1
                        visited.discard(i)
                        visited.discard(j)

                if health[current_index] > 0:
                    visited.add(current_index)
                    new_health = list(health)
                    new_health[current_index] -= 1
                    spells = dfs(tuple(new_health), current_index + 1)
                    if spells != float('inf'):
                        min_spells = min(min_spells, spells + 1)
                    new_health[current_index] += 1
                    visited.discard(current_index)

        return min_spells if current_index != n else float('inf')

    return dfs(tuple(health), 0)

import itertools

def solve(health):
    n = len(health)
    if n == 1:
        return health[0]

    min_spells = float('inf')
    for i, h in enumerate(health):
        if h == 0:
            continue
        pairs = list(itertools.combinations(range(n), 2))
        for pair in pairs:
            if pair[0][0] == i or pair[1][0] == i:
                continue
            if health[pair[0][0]] > 1 and health[pair[1][0]] > 1:
                new_health = health.copy()
                new_health[pair[0][0]] -= 1
                new_health[pair[1][0]] -= 1
                if not any(new_health):
                    return 1 + solve(new_health)

        # If we can't kill the current monster with one spell, try to kill it with two spells
        if health[i] > 1:
            new_health = health.copy()
            new_health[i] -= 2
            if not any(new_health):
                min_spells = min(min_spells, 1 + solve(new_health))

    # If we can't kill all monsters with one or two spells, we need to kill them one by one
    if min_spells == float('inf'):
        min_spells = n
        for h in health:
            min_spells += h - 1

    return min_spells

