    white_alice, black_alice, white_bob, black_bob = 0, 0, 0, 0

    while deck:
        player, count = deck.pop(), 1
        if not deck:
            deck.extendleft([0] * count)
        else:
            count += deck[0]
            deck.popleft()

        if player:
            color = player % 2
            if color == 0:
                white_alice += min(count, len(deck))
                black_alice += max(0, count - len(deck))
            else:
                white_bob += min(count, len(deck))
                black_bob += max(0, count - len(deck))

    return white_alice, black_alice, white_bob, black_bob

