import math

def solve(n, a, b):
    # Calculate the minimum number of wins and losses
    wins = math.floor((n + b - a) / 2)
    losses = n - wins

    # If the number of wins is odd, it's impossible to have any draws
    if wins % 2 == 1:
        d = 0
    else:
        d = wins // 2

    # Calculate the scores for the matches
    scores = []
    for _ in range(n):
        if _ < d:
            scores.append((0, _ * 2))  # Draw
        elif wins > 0:
            scores.append((_ * 2, _ * 2))  # Win
            wins -= 1
        else:
            scores.append((_ * 2, (_ + 1) * 2))  # Loss

    return d, scores

