def create_graph(n):
    G = nx.DiGraph()
    G.add_nodes_from(range(1, n+1))
    for i in range(1, n):
        G.add_edge(i, i+1)
        G.add_edge(i+1, i)
    return G

def hamiltonian_cycle(G):
    cycles = list(nx.simple_cycles(G))
    for cycle in cycles:
        if len(cycle) == len(G):
            return cycle
    return None

def solve(n):
    if n < 2 or n > 200000:
        return -1

    G = create_graph(n)
    cycle = hamiltonian_cycle(G)
    if cycle is None:
        return -1

    p = list(itertools.islice(itertools.cycle(cycle), n))
    for i, pi in enumerate(p):
        if pi == i+1:
            return -1
    return p

