def solve():
    for _ in range(int(input())):
        n, k = map(int, input().split())
        a = list(map(int, input().split()))

        # Use a min heap to keep track of the maximum sum of consecutive k elements
        heap = []
        for i in range(n - k + 1):
            if i + k <= n:
                heapq.heappush(heap, sum(a[i:i + k]))

        # Perform operation to maximize the score
        swaps = 0
        for i in range(k - 1):
            if (a[i] + a[n - k + i]) > a[i + 1] + a[n - k + i + 1]:
                swaps += 1
                a[i], a[i + 1] = a[i + 1], a[i]

        # Swap elements at indices h and h+k if h < h+k < n
        # This ensures that remaining operations can be performed at most once
        for i in range(k - 1):
            if (a[i] + a[i+k]) > a[i+1+k] + a[i]:
                swaps += 1
                a[i], a[i+k] = a[i+k], a[i]

        # Update the heap with the new values
        heap[:] = []
        for i in range(n - k + 1):
            if i + k <= n:
                heapq.heappush(heap, sum(a[i:i + k]))

        # Find the maximum element in the heap, which corresponds to the maximum score
        print(max(heap))

