import collections

def bfs(x, y, board):
    queue = collections.deque()
    visited = set()

    moves = [(-1, 1), (0, 1), (1, 1)]
    queue.append((x, y))
    visited.add((x, y))

    while queue:
        cur_x, cur_y = queue.popleft()

        for dx, dy in moves:
            next_x, next_y = cur_x + dx, cur_y + dy

            if 0 <= next_x < board[0] and 0 <= next_y < board[1] and (next_x, next_y) not in visited:
                if not board[next_x][next_y] and (next_x, next_y) != (board[0] - 1, board[1] - 1):
                    visited.add((next_x, next_y))
                    queue.append((next_x, next_y))

