import itertools

def divisor_sum(n):
    total, sqrt_n = 0, math.isqrt(n)
    for i in range(1, sqrt_n+1):
        if n % i == 0:
            total += i + n // i
    if sqrt_n * sqrt_n != n:
        total += sqrt_n
    return total

def interleave(num, k):
    digits = list(str(num))
    digits *= k
    return int(''.join(sorted(digits)))

def abundant_numbers(max_value):
    abundants = set()
    sums = Counter(divisor_sum(i) for i in range(1, max_value+1))
    for n, count in sums.items():
        if count > n:
            abundants.add(n)
    return abundants

def factor_interleave(abundant, k):
    factors = list(itertools.product(*list(abundant)))
    interleaved = []
    for i in range(k):
        temp = [None] * k
        j = 0
        for f in factors:
            if (not temp[j] or temp[j] != f[j]) and len(interleaved) < k:
                interleaved.append(interleave(f[j], k - (j + 1)))
                j += 1
        j -= 1
    return int(''.join(str(d) for d in interleaved))

def solve(s):
