import itertools
import numpy as np

def shortest_path(n):
    graph = np.zeros((n, n), dtype=int)
    for i in range(2, n ** 2 + 1):
        for j in range(i + 1, n ** 2 + 1):
            graph[i - 2, j - 2] = 1 if i >= j else 0
            if i * j != j:
                graph[j - 2, i - 2] = 1

    dp = np.zeros(n, dtype=int)
    dp[0] = 1
    for i in range(n):
        for j in range(i):
            dp[i] = min(dp[i], dp[j] + graph[j, i])

    # The lowest weight permutations are those with the smallest total DP value
    perms = list(itertools.permutations(range(1, n)))
    best_perm = sorted(perms, key=lambda x: sum(dp[i] for i in x))[0]
    return list(best_perm)

