def solve():
    cases = int(input())

    for _ in range(cases):
        n = int(input())
        a = list(map(int, input().split()))

        # Build the graph and topological sort it
        graph = defaultdict(list)
        in_degrees = {i: 0 for i in range(1, n+1)}
        for i in range(1, n):
            graph[a[i-1]].append((i, a[i]))
            in_degrees[i+1] += 1

        sorted_vertices = list(sorted(in_degrees, key=in_degrees.get, reverse=True))
        stack = []

        # Perform DFS starting from the vertices with 0 indegree
        for vertex in sorted_vertices:
            if in_degrees[vertex] == 0:
                stack.append(vertex)
                in_degrees[vertex] = -1  # Mark visited vertices

                while stack:
                    current = stack.pop()
                    for next_vertex, value in graph[current]:
                        if in_degrees[next_vertex] > 0:
                            in_degrees[next_vertex] -= value
                            if in_degrees[next_vertex] == 0:
                                stack.append(next_vertex)

        final_state_reached = all(val == 0 for val in in_degrees[1:])
        print("YES" if final_state_reached else "NO")

