def solve(s):
    # Record how many distinct characters we have seen each day.
    n = len(s)
    day_count = collections.defaultdict(int)
    result = collections.defaultdict(int)

    # Iterate through the string one character at a time.
    for c in s:
        day_count[min(day_count)] += 1
        result[sum(day_count.values())] += 1

    # Iterate through the possible number of days.
    for day in range(1, max(result.keys()) + 1):
        # If the number of distinct characters we can remember today is less than day,
        # then we have to wait until the next day.
        if day > day_count[day]:
            continue

        # Check if we can use each of the characters we remember from day 'day'.
        for i in range(day, 0, -1):
            if day_count[i] > day:
                break
            if day <= result[i]:
                # If we can use all the characters we remember from previous days,
                # then we can write at least 'day' characters today.
                result[day] = max(result[day], day)

    # The answer is the minimum day number in our result dictionary.
    return min(result.values())

